import React from 'react';

function DestinationGrid({ movies = [] }) {
  const dummyMovies = [
    { id: 1, title: '파묘', rate: '49%', img: 'https://image.tmdb.org/t/p/w500/lWjrLW8YBWDvvnbz2rW1kUaJ70P.jpg' },
    { id: 2, title: '범죄도시4', rate: '47%', img: 'https://image.tmdb.org/t/p/w500/z1pufUDaUixWwIdXpeF54g2nS4G.jpg' },
    { id: 3, title: '인사이드 아웃 2', rate: '49%', img: 'https://image.tmdb.org/t/p/w500/vpnVM9B6NMmQpWeZvzLvDESb2QY.jpg' },
    { id: 4, title: '웡카', rate: '49%', img: 'https://image.tmdb.org/t/p/w500/qhb1qYhjpypsM13k0e2sY1K59pW.jpg' },
  ];

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-lg font-bold text-zinc-900">박스오피스 / Top Movies</h3>
        <span className="text-xs text-[#503396] font-semibold cursor-pointer hover:underline">더 많은 영화보기 +</span>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {dummyMovies.map((movie, idx) => (
          <div key={movie.id} className="bg-white border border-zinc-200 rounded-xl overflow-hidden p-3 flex flex-col justify-between shadow-sm">
            <div className="relative h-64 rounded-lg overflow-hidden bg-zinc-100 mb-3">
              <span className="absolute top-2 left-2 bg-[#503396] text-white text-xs font-extrabold w-6 h-6 rounded-full flex items-center justify-center z-10 shadow">
                {idx + 1}
              </span>
              <img src={movie.img} alt={movie.title} className="w-full h-full object-cover" />
            </div>
            <h4 className="text-sm font-bold text-zinc-900 mb-2">{movie.title}</h4>
            <div className="flex justify-between items-center">
              <span className="text-xs text-zinc-600 font-medium">예매율 {movie.rate}</span>
              <button className="bg-[#503396]/10 hover:bg-[#503396] text-[#503396] hover:text-white text-xs font-bold px-3 py-1 rounded transition">
                예매
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default DestinationGrid;
